package mz.bam.seeky.android;
import android.content.*;import android.widget.*;import java.util.*;

public final class TaskActivity extends WorkspaceActivity {
    String pendingReport="";int page;String title(){return "Tarefas";}
    void load(){PlusUi.run(this,()->{List<StudyStore.Row> jobs;try(TaskStore db=new TaskStore(this)){jobs=db.jobs(page*20,21);}PlusUi.post(this,()->{int y=scroll.getScrollY();content.removeAllViews();if(jobs.isEmpty())note("As importações, cópias, resumos e OCR aparecem aqui.");for(int n=0;n<Math.min(20,jobs.size());n++){StudyStore.Row job=jobs.get(n);row("clock",job.s("title"),state(job.s("state"))+" · "+job.n("progress")+" / "+job.n("total")+"\n"+job.s("message"),()->menu(job));}pager(page,jobs.size()>20,()->{page--;load();},()->{page++;load();});scroll.post(()->scroll.scrollTo(0,y));});});}
    static String state(String value){switch(value){case "queued":return "Em espera";case "running":return "Em curso";case "paused":return "Pausado";case "pausing":return "A pausar…";case "cancelling":return "A cancelar…";case "cancelled":return "Cancelado";case "complete":return "Concluído";default:return "Precisa de atenção";}}
    void menu(StudyStore.Row job){String id=job.s("id"),state=job.s("state");UiPanel p=new UiPanel(this,job.s("title"),job.s("message"),"clock");if(state.equals("running"))p.action("pause","Pausar",null,false,()->TaskService.command(this,id,"pause"));else if(!job.s("type").equals("restore")&&(state.equals("paused")||state.equals("failed")||state.equals("cancelled")||state.equals("queued")))p.action("play","Retomar pendentes e falhados",null,false,()->TaskService.start(this,id));
        if(job.s("type").equals("restore")&&!Arrays.asList("complete","running","pausing").contains(state))p.action("restore","Rever e recuperar",null,false,()->BackupWork.confirm(this,id));if(job.s("type").equals("import"))p.action("document","Guardar relatório CSV",null,false,()->{pendingReport=id;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"Seeky_Importacao.csv"),92);});p.action("document","Ficheiros e resultados",null,false,()->items(id,0));if(job.s("type").equals("summary"))p.action("edit","Ver e editar resumo",null,false,()->SummaryWork.open(this,id));
        if(!state.equals("complete")&&!state.equals("cancelled"))p.action("stop","Cancelar tarefa",null,false,()->TaskService.command(this,id,"cancel"));
        if(!Arrays.asList("running","pausing","cancelling").contains(state))p.danger("Remover registo da tarefa",()->PlusUi.run(this,()->{try(TaskStore db=new TaskStore(this)){db.remove(id);}PlusUi.post(this,this::load);}));p.show();}
    void items(String id,int offset){PlusUi.run(this,()->{List<StudyStore.Row> rows;long total;try(TaskStore db=new TaskStore(this)){rows=db.items(id,null,offset,51);total=db.count(id,null);}PlusUi.post(this,()->{UiPanel p=new UiPanel(this,"Ficheiros e resultados",(offset+1)+"–"+Math.min(total,offset+50)+" / "+total,"document");for(int i=0;i<Math.min(50,rows.size());i++){StudyStore.Row r=rows.get(i);p.action("document",r.s("name").isEmpty()?"Parte "+(r.n("seq")+1):r.s("name"),r.s("state")+" · "+r.s("message"),false,()->new UiDialog.Builder(this).setTitle(r.s("name")).setMessage(r.s("message")).setPositiveButton("Fechar",null).show());}if(offset>0)p.action("back","Anterior",null,false,()->items(id,offset-50));if(rows.size()>50)p.action("arrow","Seguinte",null,false,()->items(id,offset+50));p.show();});});}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==92&&result==RESULT_OK&&data!=null&&data.getData()!=null&&!pendingReport.isEmpty()){String id=pendingReport;android.net.Uri target=data.getData();PlusUi.longRun(this,()->{try(TaskStore db=new TaskStore(this);java.io.Writer out=new java.io.OutputStreamWriter(getContentResolver().openOutputStream(target,"wt"),"UTF-8")){ImportReport.write(db,id,out);}});}}
    protected void onResume(){super.onResume();PlusUi.run(this,()->TaskService.wake(getApplicationContext()));}
    public void onCreate(android.os.Bundle state){if(state!=null)pendingReport=state.getString("report","");super.onCreate(state);}protected void onSaveInstanceState(android.os.Bundle out){out.putString("report",pendingReport);super.onSaveInstanceState(out);}

}
